{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2138-02-06 19:00:00",
      "speaker": "Doctor",
      "text": "Hi Mr. ___, I’m Dr. ___. You’re here today for your scheduled bronchoscopy and balloon dilation to help open up your airway. How are you feeling right now?"
    },
    {
      "turn_number": 2,
      "time": "2138-02-06 19:02:00",
      "speaker": "Patient",
      "text": "I’m okay, a bit nervous. My breathing’s been worse lately, especially when I walk. Is this going to help?"
    },
    {
      "turn_number": 3,
      "time": "2138-02-06 19:04:00",
      "speaker": "Doctor",
      "text": "Yes, the procedure should help. Your tracheal stenosis has been getting tighter, and this dilation will stretch it open. You’ve had this before, so you know what to expect."
    },
    {
      "turn_number": 4,
      "time": "2138-02-06 19:06:00",
      "speaker": "Patient",
      "text": "Right, I had it last month. But I’ve been short of breath again. Any risks this time?"
    },
    {
      "turn_number": 5,
      "time": "2138-02-06 19:08:00",
      "speaker": "Doctor",
      "text": "The risks are low. We’ll monitor you closely. Since you have relapsing polychondritis, we always watch for inflammation, but you’ve done well in the past."
    },
    {
      "turn_number": 6,
      "time": "2138-02-06 19:10:00",
      "speaker": "Patient",
      "text": "Okay, that makes me feel better. What happens right after?"
    },
    {
      "turn_number": 7,
      "time": "2138-02-06 19:12:00",
      "speaker": "Doctor",
      "text": "You’ll go to recovery, then come back here for overnight monitoring. We’ll check your breathing and oxygen levels. No pain expected, but we’ll manage it if needed."
    },
    {
      "turn_number": 8,
      "time": "2138-02-06 20:30:00",
      "speaker": "Doctor",
      "text": "You’re back on the floor. The procedure went smoothly—balloon dilation of the trachea and left mainstem was successful. No complications."
    },
    {
      "turn_number": 9,
      "time": "2138-02-06 20:32:00",
      "speaker": "Patient",
      "text": "That’s a relief. I don’t feel any pain. Is the biopsy going to be checked?"
    },
    {
      "turn_number": 10,
      "time": "2138-02-06 20:34:00",
      "speaker": "Doctor",
      "text": "Yes, the bronchial biopsy and wash are sent to the lab. Preliminary gram stain shows some white blood cells and gram-positive cocci, but culture results are pending."
    },
    {
      "turn_number": 11,
      "time": "2138-02-06 20:36:00",
      "speaker": "Patient",
      "text": "Is that infection? Should I be worried?"
    },
    {
      "turn_number": 12,
      "time": "2138-02-06 20:38:00",
      "speaker": "Doctor",
      "text": "Not necessarily. With your history, we often see bacteria in the airway. The stain doesn’t confirm infection. We’ll follow up on cultures, but no antibiotics are needed now."
    },
    {
      "turn_number": 13,
      "time": "2138-02-07 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs show a high white blood cell count—21.9. But it’s likely from inflammation due to your polychondritis, not infection."
    },
    {
      "turn_number": 14,
      "time": "2138-02-07 08:17:00",
      "speaker": "Patient",
      "text": "Should I get more tests? I’ve had Pseudomonas before."
    },
    {
      "turn_number": 15,
      "time": "2138-02-07 08:19:00",
      "speaker": "Doctor",
      "text": "We’re already on it. The acid-fast smear was negative, so no sign of mycobacteria this time. We’ll repeat the CBC as an outpatient to watch the count."
    },
    {
      "turn_number": 16,
      "time": "2138-02-07 15:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Oxygen is off, breathing comfortably. We’re clearing you to go home. You’ll take 40 mg prednisone daily for five days to reduce inflammation."
    },
    {
      "turn_number": 17,
      "time": "2138-02-07 15:02:00",
      "speaker": "Patient",
      "text": "Then back to my usual dose?"
    },
    {
      "turn_number": 18,
      "time": "2138-02-07 15:04:00",
      "speaker": "Doctor",
      "text": "Exactly. And keep taking your famotidine and losartan. Follow up with interventional pulmonology in four weeks for another check."
    },
    {
      "turn_number": 19,
      "time": "2138-02-07 15:06:00",
      "speaker": "Patient",
      "text": "And the biopsy results?"
    },
    {
      "turn_number": 20,
      "time": "2138-02-07 15:08:00",
      "speaker": "Doctor",
      "text": "Those will come through follow-up. Call the pulmonology team if you have fever, increased shortness of breath, or bloody secretions."
    },
    {
      "turn_number": 21,
      "time": "2138-02-07 15:10:00",
      "speaker": "Patient",
      "text": "Got it. Thanks for explaining everything."
    },
    {
      "turn_number": 22,
      "time": "2138-02-07 15:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll see you in clinic soon. Take care, and feel free to call your father to let him know you’re ready to go home."
    },
    {
      "turn_number": 23,
      "time": "2138-02-07 15:14:00",
      "speaker": "Patient",
      "text": "Will do. Appreciate all the help."
    },
    {
      "turn_number": 24,
      "time": "2138-02-07 15:16:00",
      "speaker": "Doctor",
      "text": "You did great. Just keep up with your meds and follow-up. Your condition is stable, and we’re managing it well."
    },
    {
      "turn_number": 25,
      "time": "2138-02-07 15:18:00",
      "speaker": "Patient",
      "text": "Good to hear. I’ll make sure to come back for the appointment."
    },
    {
      "turn_number": 26,
      "time": "2138-02-07 15:20:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll coordinate with rheumatology too, since your polychondritis needs ongoing care."
    },
    {
      "turn_number": 27,
      "time": "2138-02-07 15:22:00",
      "speaker": "Patient",
      "text": "Yes, Dr. ___ has been managing that. I’ll keep both visits."
    },
    {
      "turn_number": 28,
      "time": "2138-02-07 15:24:00",
      "speaker": "Doctor",
      "text": "Excellent. You’re all set. Discharge paperwork is ready. Take it easy at home, and we’ll see you soon."
    }
  ],
  "summary": {
    "admission_start": "2138-02-06 18:49:00",
    "admission_end": "2138-02-07 16:09:00",
    "summary_paragraph": "Mr. ___ was admitted for scheduled flexible bronchoscopy with balloon dilation and bronchial wash due to recurrent tracheal stenosis related to relapsing polychondritis. The procedure was performed without complications, and he remained stable throughout the admission with no respiratory distress or pain. Laboratory results showed leukocytosis, attributed to underlying inflammatory disease rather than infection. He was discharged home with a five-day course of high-dose prednisone, instructions to resume his baseline medications, and follow-up planned with interventional pulmonology in four weeks for review of biopsy and culture results. His breathing improved, and oxygen was successfully weaned prior to discharge.",
    "problems": [
      "Relapsing polychondritis",
      "Ruvalcaba-Myhre-Smith syndrome",
      "Other specified diseases of upper respiratory tract",
      "Other diseases of bronchus, not elsewhere classified",
      "Tracheostomy status",
      "Shortness of breath",
      "Essential (primary) hypertension",
      "Gastro-esophageal reflux disease without esophagitis",
      "Atrophy of testis",
      "Long term (current) use of antibiotics",
      "Carrier of other specified bacterial diseases",
      "Other diseases of pharynx",
      "Family history of other psychoactive substance abuse and dependence",
      "Family history of alcohol abuse and dependence"
    ]
  }
}
